  function load(name) {
    if (BUF[name]) return BUF[name];
    const ac3 = ENV2.core.sound.ctx();
    return BUF[name] = fetch(ENV2.ctx.base + "audio/" + name + ".mp3").then((r) => r.arrayBuffer()).then((b) => new Promise((ok, ng) => ac3.decodeAudioData(b, ok, ng))).catch(() => null);
  }
  function stopSfxVoice() {
    try {
      curVoice && curVoice.stop();
    } catch (e) {
    }
    curVoice = null;
  }
  function playFile(name) {
    const isVoice = name.startsWith("voice/");
    load(name).then((buf) => {
      if (!buf || !ENV2.root || settings.mute) return;
      const ac3 = ENV2.core.sound.ctx(), src = ac3.createBufferSource(), g = ac3.createGain();
      src.buffer = buf;
      g.gain.value = isVoice ? FILE_GAIN * VOICE_RATE : FILE_GAIN;
      src.connect(g).connect(ENV2.core.sound.sfxBus);
      if (isVoice) {
        stopSfxVoice();
        curVoice = src;
      }
      src.start();
    });
  }
  function sfx(name) {
    const m = settings.sound || "both";
    if (m === "off" || settings.mute) return;
    if (m === "voice" && !name.startsWith("voice/")) return;
    if (m === "sfx" && name.startsWith("voice/")) return;
    const now = performance.now();
    if (now - (LAST2[name] || 0) < 120) return;
    LAST2[name] = now;
    try {
      unlockAudio();
    } catch (e) {
    }
    if (FILES.includes(name)) {
      playFile(name);
      return;
    }
    const f = SYN[name];
    if (f) try {
      f();
    } catch (e) {
    }
  }
  function preloadSfx() {
    try {
      ENV2.core.sound.ctx();
      FILES.forEach(load);
    } catch (e) {
    }
  }
  function initSfx() {
    const h = (e) => {
      const b = e.target.closest && e.target.closest("button");
      if (!b || !ENV2.root || !ENV2.root.contains(b) || b.id === "cutBtn" || b.dataset.nosfx || b.disabled) return;
      if (b.dataset.play || b.dataset.study === "make") return;
      sfx(/^[←‹＜]|戻る|もどる|閉じる|やめる/.test((b.textContent || "").trim()) ? "se/back" : "se/tap");
    };
    document.addEventListener("click", h, true);
    ENV2.offs.push(() => document.removeEventListener("click", h, true));
  }

