      ...Object.keys(byCat).sort().map((c, i) => ({ label: `\u77ED\u6587\uFF1A${c}`, level: null, sub: `\u7528\u9014\u5225\u30FB${byCat[c].length}\u6587`, ord: 900 + i, go: () => startShortPractice(byCat[c], `\u77ED\u6587\uFF1A${c}`) }))
