      const title = el3.querySelector("#title"), mo = new MutationObserver(() => ctx.showBack(!title.hidden && !ctx.core.reader.isOpen && !ENV2.make.visible() && !ENV2.story.visible()));
      mo.observe(title, { attributes: true, attributeFilter: ["hidden"] });
      showTitle2();
